import argparse
import datetime
import json
import sys
from typing import List

from kitty import ledger, reports, store
from kitty.errors import KittyError
from kitty.store import STATE_FILE


class KittyParser(argparse.ArgumentParser):
    def error(self, message):
        raise KittyError(message)


def _parser() -> KittyParser:
    p = KittyParser(prog="kitty", allow_abbrev=False)
    top = p.add_subparsers(dest="command", required=True)

    def add(sub, name):
        return sub.add_parser(name, allow_abbrev=False)

    c = add(top, "init")
    c.add_argument("currency")

    m = add(top, "member")
    msub = m.add_subparsers(dest="action", required=True)
    for name in ("add", "remove"):
        add(msub, name).add_argument("name")
    add(msub, "list")

    e = add(top, "expense")
    esub = e.add_subparsers(dest="action", required=True)
    ea = add(esub, "add")
    ea.add_argument("payer")
    ea.add_argument("amount")
    ea.add_argument("description", nargs="+")
    for opt in ("among", "exact", "shares", "percent", "currency", "date", "category"):
        ea.add_argument("--" + opt)
    add(esub, "list")
    add(esub, "remove").add_argument("id")

    pay = add(top, "payment")
    psub = pay.add_subparsers(dest="action", required=True)
    pa = add(psub, "add")
    for a in ("sender", "receiver", "amount"):
        pa.add_argument(a)
    pa.add_argument("--currency")
    pa.add_argument("--date")

    r = add(top, "rate")
    rsub = r.add_subparsers(dest="action", required=True)
    rs = add(rsub, "set")
    rs.add_argument("currency")
    rs.add_argument("rate")

    add(top, "balances")
    add(top, "settle")
    add(top, "history").add_argument("name")
    add(top, "report")
    add(top, "export").add_argument("file")
    return p


def _today() -> str:
    return datetime.date.today().isoformat()


def _run(args) -> None:
    cmd = args.command
    if cmd == "init":
        store.init(STATE_FILE, args.currency)
        return
    state = store.load(STATE_FILE)
    out = None
    print_after = None
    write = False
    if cmd == "member":
        if args.action == "add":
            ledger.add_member(state, args.name)
            write = True
        elif args.action == "remove":
            ledger.remove_member(state, args.name)
            write = True
        else:
            out = ledger.list_members(state)
    elif cmd == "expense":
        if args.action == "add":
            new_id = ledger.add_expense(
                state, args.payer, args.amount, " ".join(args.description),
                date=args.date if args.date is not None else _today(),
                among=args.among, exact=args.exact, shares=args.shares,
                percent=args.percent, currency=args.currency, category=args.category)
            write = True
            print_after = str(new_id)
        elif args.action == "remove":
            ledger.remove_expense(state, args.id)
            write = True
        else:
            out = ledger.list_expenses(state)
    elif cmd == "payment":
        ledger.add_payment(state, args.sender, args.receiver, args.amount,
                           date=args.date if args.date is not None else _today(),
                           currency=args.currency)
        write = True
    elif cmd == "rate":
        ledger.set_rate(state, args.currency, args.rate)
        write = True
    elif cmd == "balances":
        out = reports.balances(state)
    elif cmd == "settle":
        out = reports.settle(state)
    elif cmd == "history":
        out = reports.history(state, args.name)
    elif cmd == "report":
        out = reports.category_report(state)
    elif cmd == "export":
        reports.export_csv(state, args.file, state_path=STATE_FILE)
    if write:
        store.save(STATE_FILE, state)
    if print_after is not None:
        print(print_after)
    if out is not None:
        print(json.dumps(out, ensure_ascii=False))


def main(argv: List[str]) -> int:
    try:
        args = _parser().parse_args(argv)
        _run(args)
    except KittyError as e:
        print("error: %s" % e, file=sys.stderr)
        return 1
    except Exception as e:   # safety net: never show a traceback
        detail = " ".join(str(e).split())
        print("error: internal error: %s: %s" % (type(e).__name__, detail), file=sys.stderr)
        return 1
    return 0
"""Pure state-changing functions; the CLI saves only on success."""
import re
from decimal import Decimal
from typing import List, Optional, Tuple

from kitty.errors import KittyError
from kitty.money import (exact as exact_math, fmt, parse_amount,
                         parse_currency, parse_date, parse_positive, plain,
                         split, to_base)


def find_member(state: dict, name: str) -> str:
    key = name.strip().casefold()
    for m in state["members"]:
        if m.casefold() == key:
            return m
    raise KittyError("unknown member: %s" % name.strip())


def add_member(state: dict, name: str) -> None:
    name = name.strip()
    if not name:
        raise KittyError("member name cannot be empty")
    if "," in name or "=" in name:
        raise KittyError("member name cannot contain ',' or '='")
    key = name.casefold()
    for m in state["members"]:
        if m.casefold() == key:
            raise KittyError("member already exists: %s" % m)
    state["members"].append(name)


def remove_member(state: dict, name: str) -> None:
    m = find_member(state, name)
    for e in state["expenses"]:
        if e["payer"] == m or m in e["shares"]:
            raise KittyError("cannot remove %s: appears in expenses" % m)
    for p in state["payments"]:
        if p["from"] == m or p["to"] == m:
            raise KittyError("cannot remove %s: appears in payments" % m)
    state["members"].remove(m)


def list_members(state: dict) -> List[str]:
    return list(state["members"])


def set_rate(state: dict, currency: str, rate: str) -> None:
    cur = parse_currency(currency)
    if cur == state["base_currency"]:
        raise KittyError("cannot set a rate for the base currency %s" % cur)
    value = parse_positive(rate, "rate")
    state["rates"][cur] = plain(value)


def _rate_for(state: dict, currency: Optional[str]) -> Tuple[str, Decimal]:
    if currency is None:
        return state["base_currency"], Decimal(1)
    cur = parse_currency(currency)
    if cur == state["base_currency"]:
        return cur, Decimal(1)
    if cur not in state["rates"]:
        raise KittyError("no rate set for %s; use 'rate set %s RATE'" % (cur, cur))
    return cur, Decimal(state["rates"][cur])


def _convert(amount: Decimal, cur: str, rate: Decimal) -> Decimal:
    base = to_base(amount, rate)
    if base == 0:
        raise KittyError("the converted amount is zero (%s %s at rate %s); check the rate"
                         % (fmt(amount), cur, plain(rate)))
    return base


def _parse_pairs(state: dict, text: str) -> List[Tuple[str, str]]:
    out = []  # type: List[Tuple[str, str]]
    seen = set()
    for item in text.split(","):
        if item.count("=") != 1:
            raise KittyError("expected NAME=VALUE, got '%s'" % item.strip())
        name, value = item.split("=")
        name, value = name.strip(), value.strip()
        if not name or not value:
            raise KittyError("expected NAME=VALUE, got '%s'" % item.strip())
        m = find_member(state, name)
        if m in seen:
            raise KittyError("duplicate name in split: %s" % m)
        seen.add(m)
        out.append((m, value))
    return out


def _parse_names(state: dict, text: str) -> List[str]:
    out = []  # type: List[str]
    for item in text.split(","):
        if not item.strip():
            raise KittyError("empty name in split")
        m = find_member(state, item)
        if m in out:
            raise KittyError("duplicate name in split: %s" % m)
        out.append(m)
    return out


@exact_math
def add_expense(state: dict, payer: str, amount: str, description: str, *,
                date: str, among: Optional[str] = None,
                exact: Optional[str] = None, shares: Optional[str] = None,
                percent: Optional[str] = None, currency: Optional[str] = None,
                category: Optional[str] = None) -> int:
    payer = find_member(state, payer)
    amt = parse_amount(amount)
    description = description.strip()
    if not description:
        raise KittyError("description cannot be empty")
    date = parse_date(date)
    category = "other" if category is None else category.strip().lower()
    if not category:
        raise KittyError("category cannot be empty")
    if sum(1 for o in (among, exact, shares, percent) if o is not None) > 1:
        raise KittyError("use at most one of --among, --exact, --shares, --percent")
    cur, rate = _rate_for(state, currency)
    base = _convert(amt, cur, rate)

    names = []  # type: List[str]
    weights = []  # type: List[Decimal]
    if exact is not None:
        for n, v in _parse_pairs(state, exact):
            names.append(n)
            weights.append(parse_amount(v))
        if sum(weights) != amt:
            raise KittyError("exact amounts must add up to %s" % fmt(amt))
    elif shares is not None:
        for n, v in _parse_pairs(state, shares):
            names.append(n)
            weights.append(parse_positive(v, "share"))
    elif percent is not None:
        for n, v in _parse_pairs(state, percent):
            names.append(n)
            weights.append(parse_positive(v, "percent"))
        if sum(weights) != Decimal(100):
            raise KittyError("percentages must add up to 100")
    else:
        names = _parse_names(state, among) if among is not None else list(state["members"])
        if not names:
            raise KittyError("no members to split among")
        weights = [Decimal(1)] * len(names)

    parts = split(base, weights)
    eid = state["next_id"]
    state["expenses"].append({
        "id": eid,
        "seq": state["next_seq"],
        "date": date,
        "payer": payer,
        "description": description,
        "amount": fmt(amt),
        "currency": cur,
        "rate": plain(rate),
        "base_amount": fmt(base),
        "category": category,
        "shares": {n: fmt(p) for n, p in zip(names, parts)},
    })
    state["next_id"] = eid + 1
    state["next_seq"] += 1
    return eid


def remove_expense(state: dict, expense_id: str) -> None:
    if not re.fullmatch(r"\d+", expense_id, re.ASCII):
        raise KittyError("invalid expense ID: '%s'" % expense_id)
    n = int(expense_id)
    for i, e in enumerate(state["expenses"]):
        if e["id"] == n:
            del state["expenses"][i]
            return
    raise KittyError("no such expense: %d" % n)


def list_expenses(state: dict) -> List[dict]:
    out = []
    for e in sorted(state["expenses"], key=lambda x: x["id"]):
        out.append({
            "id": e["id"], "date": e["date"], "payer": e["payer"],
            "description": e["description"], "amount": e["amount"],
            "currency": e["currency"], "base_amount": e["base_amount"],
            "category": e["category"], "shares": dict(e["shares"]),
        })
    return out


def add_payment(state: dict, sender: str, receiver: str, amount: str, *,
                date: str, currency: Optional[str] = None) -> None:
    frm = find_member(state, sender)
    to = find_member(state, receiver)
    if frm == to:
        raise KittyError("cannot pay yourself")
    amt = parse_amount(amount)
    date = parse_date(date)
    cur, rate = _rate_for(state, currency)
    base = _convert(amt, cur, rate)
    state["payments"].append({
        "seq": state["next_seq"],
        "date": date,
        "from": frm,
        "to": to,
        "amount": fmt(amt),
        "currency": cur,
        "rate": plain(rate),
        "base_amount": fmt(base),
    })
    state["next_seq"] += 1
import functools
import re
from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP, localcontext
from typing import List

from kitty.errors import KittyError

CENT = Decimal("0.01")

_AMOUNT = re.compile(r"\d{1,12}(\.\d{1,2})?", re.ASCII)
_POSITIVE = re.compile(r"\d{1,12}(\.\d{1,28})?", re.ASCII)
_DATE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)
_CURRENCY = re.compile(r"[A-Za-z]{3}", re.ASCII)

# Amounts have at most 14 significant digits and rates at most 40, so a
# product has at most 54 and a base amount at most 26; sums of many of them
# stay far below this. The default 28-digit context would round silently.
PRECISION = 100


def exact(fn):
    """Run fn under a local high-precision decimal context (does not leak)."""
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        with localcontext() as ctx:
            ctx.prec = PRECISION
            return fn(*args, **kwargs)
    return wrapper


def parse_amount(text: str) -> Decimal:
    if not re.fullmatch(_AMOUNT, text) or Decimal(text) <= 0:
        raise KittyError("invalid amount '%s': use a positive number with at most 2 decimals" % text)
    return Decimal(text).quantize(CENT)


def parse_positive(text: str, what: str) -> Decimal:
    if not re.fullmatch(_POSITIVE, text) or Decimal(text) <= 0:
        raise KittyError("invalid %s '%s': must be a positive number" % (what, text))
    return Decimal(text)


def plain(value: Decimal) -> str:
    """A decimal as a plain string, never in exponent form (1E-7)."""
    return format(value, "f")


@exact
def fmt(value: Decimal) -> str:
    q = value.quantize(CENT, rounding=ROUND_HALF_UP)
    if q == 0:
        q = abs(q)
    return str(q)


@exact
def to_base(amount: Decimal, rate: Decimal) -> Decimal:
    return (amount * rate).quantize(CENT, rounding=ROUND_HALF_UP)


@exact
def split(total: Decimal, weights: List[Decimal]) -> List[Decimal]:
    s = sum(weights)
    cents = total.scaleb(2)
    # `//` truncates exactly (no intermediate rounding); all values are positive
    parts = [(cents * w // s).scaleb(-2) for w in weights]
    leftover = int((total - sum(parts)).scaleb(2))   # always < len(weights)
    for i in range(leftover):
        parts[i] += CENT
    return parts


def parse_date(text: str) -> str:
    if not re.fullmatch(_DATE, text):
        raise KittyError("invalid date '%s': use YYYY-MM-DD" % text)
    try:
        datetime.strptime(text, "%Y-%m-%d")
    except ValueError:
        raise KittyError("invalid date '%s': not a real date" % text)
    return text


def parse_currency(text: str) -> str:
    if not re.fullmatch(_CURRENCY, text):
        raise KittyError("invalid currency '%s': use a 3-letter code" % text)
    return text.upper()
import csv
import os
from decimal import Decimal
from typing import Dict, List, Optional

from kitty import ledger, store
from kitty.errors import KittyError
from kitty.money import exact, fmt


@exact
def raw_balances(state: dict) -> Dict[str, Decimal]:
    bal = {n: Decimal("0") for n in state["members"]}
    for e in state["expenses"]:
        bal[e["payer"]] += Decimal(e["base_amount"])
        for name, share in e["shares"].items():
            bal[name] -= Decimal(share)
    for p in state["payments"]:
        amt = Decimal(p["base_amount"])
        bal[p["from"]] += amt
        bal[p["to"]] -= amt
    return bal


@exact
def balances(state: dict) -> Dict[str, str]:
    return {n: fmt(b) for n, b in raw_balances(state).items()}


@exact
def settle(state: dict) -> List[dict]:
    bal = raw_balances(state)
    out = []
    while True:
        debtors = [n for n, b in bal.items() if b < 0]
        creditors = [n for n, b in bal.items() if b > 0]
        if not debtors or not creditors:
            break
        d = min(debtors, key=lambda n: (bal[n], n.casefold()))
        c = min(creditors, key=lambda n: (-bal[n], n.casefold()))
        amt = min(-bal[d], bal[c])
        out.append({"from": d, "to": c, "amount": fmt(amt)})
        bal[d] += amt
        bal[c] -= amt
    return out


@exact
def history(state: dict, name: str) -> List[dict]:
    name = ledger.find_member(state, name)
    items = []
    for e in state["expenses"]:
        if e["payer"] != name and name not in e["shares"]:
            continue
        change = Decimal("0")
        if e["payer"] == name:
            change += Decimal(e["base_amount"])
        change -= Decimal(e["shares"].get(name, "0"))
        items.append((e["date"], e["seq"], e["description"], change))
    for p in state["payments"]:
        base = Decimal(p["base_amount"])
        if p["from"] == name:
            items.append((p["date"], p["seq"], "Payment to " + p["to"], base))
        if p["to"] == name:
            items.append((p["date"], p["seq"], "Payment from " + p["from"], -base))
    items.sort(key=lambda t: (t[0], t[1]))
    out = []
    running = Decimal("0")
    for date, _seq, desc, change in items:
        running += change
        out.append({"date": date, "description": desc,
                    "change": fmt(change), "balance": fmt(running)})
    return out


@exact
def category_report(state: dict) -> Dict[str, Dict[str, str]]:
    totals = {}  # type: Dict[str, Dict[str, Decimal]]
    for e in state["expenses"]:
        cat = totals.setdefault(e["category"], {})
        for name, share in e["shares"].items():
            cat[name] = cat.get(name, Decimal("0")) + Decimal(share)
    out = {}
    for cat in sorted(totals):
        out[cat] = {n: fmt(totals[cat][n]) for n in state["members"] if n in totals[cat]}
    return out


def export_csv(state: dict, path: str, state_path: Optional[str] = None) -> None:
    """Write the CSV atomically; refuse if path is the state file itself."""
    if state_path is not None:
        try:
            same = os.path.exists(path) and os.path.samefile(path, state_path)
        except OSError as exc:
            raise KittyError("cannot write %s: %s" % (path, exc))
        if same:
            raise KittyError("cannot export to %s: that is the kitty's own data file "
                             "(%s); choose another file name" % (path, state_path))

    def write(f):
        w = csv.writer(f)
        w.writerow(["id", "date", "payer", "description", "amount",
                    "currency", "category", "base_amount"])
        for e in sorted(state["expenses"], key=lambda x: x["id"]):
            w.writerow([e["id"], e["date"], e["payer"], e["description"],
                        fmt(Decimal(e["amount"])), e["currency"], e["category"],
                        fmt(Decimal(e["base_amount"]))])
    store.write_atomically(path, write, newline="")
class KittyError(Exception):
    """A refusal; str(e) is the message shown to the user."""
import sys

from kitty.cli import main

sys.exit(main(sys.argv[1:]))

