import functools
import re
from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP, localcontext
from typing import List

from kitty.errors import KittyError

CENT = Decimal("0.01")

_AMOUNT = re.compile(r"\d{1,12}(\.\d{1,2})?", re.ASCII)
_POSITIVE = re.compile(r"\d{1,12}(\.\d{1,28})?", re.ASCII)
_DATE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)
_CURRENCY = re.compile(r"[A-Za-z]{3}", re.ASCII)

# Amounts have at most 14 significant digits and rates at most 40, so a
# product has at most 54 and a base amount at most 26; sums of many of them
# stay far below this. The default 28-digit context would round silently.
PRECISION = 100


def exact(fn):
    """Run fn under a local high-precision decimal context (does not leak)."""
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        with localcontext() as ctx:
            ctx.prec = PRECISION
            return fn(*args, **kwargs)
    return wrapper


def parse_amount(text: str) -> Decimal:
    if not re.fullmatch(_AMOUNT, text) or Decimal(text) <= 0:
        raise KittyError("invalid amount '%s': use a positive number with at most 2 decimals" % text)
    return Decimal(text).quantize(CENT)


def parse_positive(text: str, what: str) -> Decimal:
    if not re.fullmatch(_POSITIVE, text) or Decimal(text) <= 0:
        raise KittyError("invalid %s '%s': must be a positive number" % (what, text))
    return Decimal(text)


def plain(value: Decimal) -> str:
    """A decimal as a plain string, never in exponent form (1E-7)."""
    return format(value, "f")


@exact
def fmt(value: Decimal) -> str:
    q = value.quantize(CENT, rounding=ROUND_HALF_UP)
    if q == 0:
        q = abs(q)
    return str(q)


@exact
def to_base(amount: Decimal, rate: Decimal) -> Decimal:
    return (amount * rate).quantize(CENT, rounding=ROUND_HALF_UP)


@exact
def split(total: Decimal, weights: List[Decimal]) -> List[Decimal]:
    s = sum(weights)
    cents = total.scaleb(2)
    # `//` truncates exactly (no intermediate rounding); all values are positive
    parts = [(cents * w // s).scaleb(-2) for w in weights]
    leftover = int((total - sum(parts)).scaleb(2))   # always < len(weights)
    for i in range(leftover):
        parts[i] += CENT
    return parts


def parse_date(text: str) -> str:
    if not re.fullmatch(_DATE, text):
        raise KittyError("invalid date '%s': use YYYY-MM-DD" % text)
    try:
        datetime.strptime(text, "%Y-%m-%d")
    except ValueError:
        raise KittyError("invalid date '%s': not a real date" % text)
    return text


def parse_currency(text: str) -> str:
    if not re.fullmatch(_CURRENCY, text):
        raise KittyError("invalid currency '%s': use a 3-letter code" % text)
    return text.upper()
import csv
import os
from decimal import Decimal
from typing import Dict, List, Optional

from kitty import ledger, store
from kitty.errors import KittyError
from kitty.money import exact, fmt


@exact
def raw_balances(state: dict) -> Dict[str, Decimal]:
    bal = {n: Decimal("0") for n in state["members"]}
    for e in state["expenses"]:
        bal[e["payer"]] += Decimal(e["base_amount"])
        for name, share in e["shares"].items():
            bal[name] -= Decimal(share)
    for p in state["payments"]:
        amt = Decimal(p["base_amount"])
        bal[p["from"]] += amt
        bal[p["to"]] -= amt
    return bal


@exact
def balances(state: dict) -> Dict[str, str]:
    return {n: fmt(b) for n, b in raw_balances(state).items()}


@exact
def settle(state: dict) -> List[dict]:
    bal = raw_balances(state)
    out = []
    while True:
        debtors = [n for n, b in bal.items() if b < 0]
        creditors = [n for n, b in bal.items() if b > 0]
        if not debtors or not creditors:
            break
        d = min(debtors, key=lambda n: (bal[n], n.casefold()))
        c = min(creditors, key=lambda n: (-bal[n], n.casefold()))
        amt = min(-bal[d], bal[c])
        out.append({"from": d, "to": c, "amount": fmt(amt)})
        bal[d] += amt
        bal[c] -= amt
    return out


@exact
def history(state: dict, name: str) -> List[dict]:
    name = ledger.find_member(state, name)
    items = []
    for e in state["expenses"]:
        if e["payer"] != name and name not in e["shares"]:
            continue
        change = Decimal("0")
        if e["payer"] == name:
            change += Decimal(e["base_amount"])
        change -= Decimal(e["shares"].get(name, "0"))
        items.append((e["date"], e["seq"], e["description"], change))
    for p in state["payments"]:
        base = Decimal(p["base_amount"])
        if p["from"] == name:
            items.append((p["date"], p["seq"], "Payment to " + p["to"], base))
        if p["to"] == name:
            items.append((p["date"], p["seq"], "Payment from " + p["from"], -base))
    items.sort(key=lambda t: (t[0], t[1]))
    out = []
    running = Decimal("0")
    for date, _seq, desc, change in items:
        running += change
        out.append({"date": date, "description": desc,
                    "change": fmt(change), "balance": fmt(running)})
    return out


@exact
def category_report(state: dict) -> Dict[str, Dict[str, str]]:
    totals = {}  # type: Dict[str, Dict[str, Decimal]]
    for e in state["expenses"]:
        cat = totals.setdefault(e["category"], {})
        for name, share in e["shares"].items():
            cat[name] = cat.get(name, Decimal("0")) + Decimal(share)
    out = {}
    for cat in sorted(totals):
        out[cat] = {n: fmt(totals[cat][n]) for n in state["members"] if n in totals[cat]}
    return out


def export_csv(state: dict, path: str, state_path: Optional[str] = None) -> None:
    """Write the CSV atomically; refuse if path is the state file itself."""
    if state_path is not None:
        try:
            same = os.path.exists(path) and os.path.samefile(path, state_path)
        except OSError as exc:
            raise KittyError("cannot write %s: %s" % (path, exc))
        if same:
            raise KittyError("cannot export to %s: that is the kitty's own data file "
                             "(%s); choose another file name" % (path, state_path))

    def write(f):
        w = csv.writer(f)
        w.writerow(["id", "date", "payer", "description", "amount",
                    "currency", "category", "base_amount"])
        for e in sorted(state["expenses"], key=lambda x: x["id"]):
            w.writerow([e["id"], e["date"], e["payer"], e["description"],
                        fmt(Decimal(e["amount"])), e["currency"], e["category"],
                        fmt(Decimal(e["base_amount"]))])
    store.write_atomically(path, write, newline="")
class KittyError(Exception):
    """A refusal; str(e) is the message shown to the user."""
